python3 -I -c "
import json
p=json.load(open('clientes/verdeluz-teste/entrega/ativos-aprovados/plano-de-acao/plano-de-acao-estrategico.json'))
print(json.dumps({k:p[k] for k in ['data_referencia','janela_prova','fim_ciclo','empresa_agencia','agencia_parceira','como_funciona']},ensure_ascii=False))
print(json.dumps(p['abertura'],ensure_ascii=False)[:3000])
for f in p['fases']:
    print('FASE',json.dumps({k:v for k,v in f.items() if k!='acoes'},ensure_ascii=False)); 
    for a in f['acoes']:
        print(a['numero'],'|',a['acao'],'|',a.get('dono'),'|',a.get('inicio'),'-',a.get('prazo'),'|',a.get('solucao'),'|dep',a.get('depende_de'),'|',a.get('alavanca'))
"

